# ==========================================================
# DISTILLATION COLUMN DATA ANALYSIS GENERATED BY DWSIM SIMULATION
# ==========================================================
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
# ==========================================================
# LOAD DATA
# ==========================================================
datapoints = pd.read_excel(r"C:\Users\user\Desktop\python code test.xlsx")
# Sort data
dataanalysis = datapoints.sort_values(by="molar flow rate").reset_index(drop=True)
# Remove duplicate rows
main_data = dataanalysis.drop_duplicates()
# ==========================================================
# DATA TABLE INFORMATION
# ==========================================================
print("\n================ FIRST 5 ROWS ================\n")
print(main_data.head())
print("\n================ LAST 5 ROWS ================\n")
print(main_data.tail())
print("\n================ SHAPE ================\n")
print(main_data.shape)
print("\n================ COLUMNS ================\n")
print(main_data.columns)
print("\n================ DATA TYPES ================\n")
print(main_data.dtypes)
print("\n================ INFORMATION ================\n")
main_data.info()
print("\n================ STATISTICAL SUMMARY ================\n")
print(main_data.describe())
print("\n================ MISSING VALUES ================\n")
print(main_data.isnull().sum())
# ==========================================================
# STATISTICS 
# ==========================================================
distillated_mean = main_data[3].mean()
distillated_median = main_data[3].median()
distillated_std = main_data[3].std()
print("Top Product (3)")
print(f"Mean               : {distillated_mean:.4f}")
print(f"Median             : {distillated_median:.4f}")
print(f"Standard Deviation : {distillated_std:.4f}")
# ==========================================================
# PLOTTING STYLE
# ==========================================================
plt.style.use("ggplot")
plt.figure(figsize=(8, 5))
# ==========================================================
# GRAPH 1: Molar Flow Rate(kmol/h) vs Top Product (3)
# ==========================================================
import matplotlib.pyplot as plt
# Calculate mean, median and mode
mean = main_data[3].mean()
median = main_data[3].median()
mode = main_data[3].mode()[0]
# Plot Molar Flow Rate vs Top Product (3)
plt.scatter(main_data["molar flow rate"], main_data[3],alpha=0.5, 
            label="Data Points",color="red")
# Mean, Median and Mode lines
plt.axhline(mean, linestyle="--",label="mean", color="yellow", linewidth=2)
plt.axhline(median, linestyle=":",label ="median", color="blue", linewidth=2)
plt.axhline(mode, linestyle="-.",label="mode", color="green", linewidth=2)
plt.text(
    0.95,
    0.05,
    f"Mean = {mean:.3f}\nMedian = {median:.3f}\nMode = {mode:.3f}",
    transform=plt.gca().transAxes
)
# Labels and title
plt.xlabel("Molar Flow Rate")
plt.ylabel("Top Product (3)")
plt.title("Molar Flow Rate vs Top Product (3)")
plt.legend()
plt.show()
